/// <summary>
/// A script whose functions X++ code calls by name, with arguments and a return value.
/// A call runs in the transaction and with the rights of the caller: the role, the log and the parameters of the
/// interpreter don't apply. Whoever can change the text decides what runs, so the table that holds it needs its own security.
/// </summary>
public final class MXTXppScript
{
    private static XppInterpreter.Interpreter.CompiledScriptCache scripts;

    private XppInterpreter.Interpreter.CompiledScript script;

}

Method.Source:
/// <summary>
/// The text is parsed the first time the session uses it, and found by its text after that: X++ keeps a static field for each session.
/// A text with errors gives a script too: isValid, parseErrors and validate say what is wrong.
/// </summary>
public static MXTXppScript newFromSource(str _source)
{
    MXTXppScript ret = new MXTXppScript();

    ret.initFromSource(_source);

    return ret;
}

/// <summary>
/// The errors of the text, as "Line n, position m: message"
/// </summary>
public List parseErrors()
{
    return MXTXppInterpreterExecutionResult::construct(script.ParseResult).parseErrors();
}

public boolean hasFunction(str _function)
{
    return script.FindFunction(_function) != null;
}

/// <summary>
/// For the validateWrite of the table that holds the text: reports its errors as checkFailed does
/// </summary>
/// <param name = "_function">A function that the script must have</param>
public boolean validate(str _function = '')
{
    boolean        ret = true;
    ListEnumerator errors = this.parseErrors().getEnumerator();

    while (errors.moveNext())
    {
        ret = checkFailed(errors.current());
    }

    if (ret && _function && !this.hasFunction(_function))
    {
        ret = checkFailed(strFmt("@MXT:ScriptFunctionNotFound", _function));
    }

    return ret;
}

/// <summary>
/// Runs a function of the script in the transaction of the caller. A record or an object that is passed is the one
/// of the caller, so the function changes it for the caller. The statements outside the functions don't run,
/// and an exception of the function reaches the caller.
/// </summary>
/// <returns>What the function returns, converted to its return type</returns>
public anytype call(
    str     _function,
    anytype _argument1 = '',
    anytype _argument2 = '',
    anytype _argument3 = '',
    anytype _argument4 = '',
    anytype _argument5 = '',
    anytype _argument6 = '',
    anytype _argument7 = '',
    anytype _argument8 = '')
{
    int argumentCount = 8;

    if (prmIsDefault(_argument1))
    {
        argumentCount = 0;
    }
    else if (prmIsDefault(_argument2))
    {
        argumentCount = 1;
    }
    else if (prmIsDefault(_argument3))
    {
        argumentCount = 2;
    }
    else if (prmIsDefault(_argument4))
    {
        argumentCount = 3;
    }
    else if (prmIsDefault(_argument5))
    {
        argumentCount = 4;
    }
    else if (prmIsDefault(_argument6))
    {
        argumentCount = 5;
    }
    else if (prmIsDefault(_argument7))
    {
        argumentCount = 6;
    }
    else if (prmIsDefault(_argument8))
    {
        argumentCount = 7;
    }

    return this.callWithArguments(_function, MXTXppScript::argumentArray(argumentCount,
        _argument1, _argument2, _argument3, _argument4, _argument5, _argument6, _argument7, _argument8));
}

/// <summary>
/// newFromSource and call in one step, for code that doesn't keep the script object. The platform charges every
/// entry into this model from a model of another publisher, and this is one entry instead of two.
/// </summary>
/// <returns>What the function returns, converted to its return type</returns>
public static anytype callFromSource(
    str     _source,
    str     _function,
    anytype _argument1 = '',
    anytype _argument2 = '',
    anytype _argument3 = '',
    anytype _argument4 = '',
    anytype _argument5 = '',
    anytype _argument6 = '',
    anytype _argument7 = '',
    anytype _argument8 = '')
{
    int argumentCount = 8;

    if (prmIsDefault(_argument1))
    {
        argumentCount = 0;
    }
    else if (prmIsDefault(_argument2))
    {
        argumentCount = 1;
    }
    else if (prmIsDefault(_argument3))
    {
        argumentCount = 2;
    }
    else if (prmIsDefault(_argument4))
    {
        argumentCount = 3;
    }
    else if (prmIsDefault(_argument5))
    {
        argumentCount = 4;
    }
    else if (prmIsDefault(_argument6))
    {
        argumentCount = 5;
    }
    else if (prmIsDefault(_argument7))
    {
        argumentCount = 6;
    }
    else if (prmIsDefault(_argument8))
    {
        argumentCount = 7;
    }

    MXTXppScript script = MXTXppScript::newFromSource(_source);

    return script.callWithArguments(_function, MXTXppScript::argumentArray(argumentCount,
        _argument1, _argument2, _argument3, _argument4, _argument5, _argument6, _argument7, _argument8));
}

private static System.Object[] argumentArray(
    int     _argumentCount,
    anytype _argument1,
    anytype _argument2,
    anytype _argument3,
    anytype _argument4,
    anytype _argument5,
    anytype _argument6,
    anytype _argument7,
    anytype _argument8)
{
    System.Object[] arguments = new System.Object[_argumentCount]();

    if (_argumentCount >= 1)
    {
        arguments.SetValue(_argument1, 0);
    }
    if (_argumentCount >= 2)
    {
        arguments.SetValue(_argument2, 1);
    }
    if (_argumentCount >= 3)
    {
        arguments.SetValue(_argument3, 2);
    }
    if (_argumentCount >= 4)
    {
        arguments.SetValue(_argument4, 3);
    }
    if (_argumentCount >= 5)
    {
        arguments.SetValue(_argument5, 4);
    }
    if (_argumentCount >= 6)
    {
        arguments.SetValue(_argument6, 5);
    }
    if (_argumentCount >= 7)
    {
        arguments.SetValue(_argument7, 6);
    }
    if (_argumentCount >= 8)
    {
        arguments.SetValue(_argument8, 7);
    }

    return arguments;
}

private anytype callWithArguments(str _function, System.Object[] _arguments)
{
    XppInterpreter.Interpreter.ScriptFunction function = this.findFunction(_function, _arguments.get_Length());

    return function.Call(_arguments);
}

private XppInterpreter.Interpreter.ScriptFunction findFunction(str _function, int _argumentCount)
{
    if (!script.IsCorrect)
    {
        ListEnumerator errors = this.parseErrors().getEnumerator();

        while (errors.moveNext())
        {
            error(errors.current());
        }

        throw error("@MXT:ScriptNotValid");
    }

    XppInterpreter.Interpreter.ScriptFunction function = script.FindFunction(_function);

    if (function == null)
    {
        throw error(strFmt("@MXT:ScriptFunctionNotFound", _function));
    }

    if (!function.Accepts(_argumentCount))
    {
        throw error(strFmt("@MXT:ScriptFunctionArguments", _function, _argumentCount));
    }

    return function;
}
